"""Heraldia advancements ("Heraldia" tab): data only, generated by walking the villages and the unique-structure registry.

Tree (ids heraldia:<path>, texts advancements.heraldia.<path with dots>.title/.description):
  raiz                         enter a Heraldia village or a unique structure
  aldeas/<familia>             enter a village of that family (structure tag heraldia:aldeas/<familia>)
  aldeas/todas                 (challenge) all 12 families
  unicas/<id>/descubrir        enter the structure (minecraft:location with structures heraldia:unicas/<id>)
  unicas/<id>/guardian         kill its guardian: Tags heraldia_guardian.<id> (pack.tag_guardians) and its mob type
                               (minecraft:entity_tags predicate of 26.3)
  unicas/<id>/tesoro           open the treasure chest (player_generates_container_loot of its tables) or obtain
                               an item found only in it (fixed-content chests)
  unicas/<id>/<extra>          the module's own advancements
  unicas/todas                 (challenge) discover all the unique structures
  unicas/trofeos               (challenge) obtain each guardian's trophy (TROPHY of each module, custom_data
                               heraldia_trofeo; one inventory_changed criterion per trophy, all required)
  medianas/descubrir           enter any medium structure; medianas/todas: one of each type in the
                               overworld; medianas/nether and medianas/end: one of each type in that dimension
  medianas/<id>/<extra>        advancements specific to a type of medium structure (the module's ADVANCEMENTS: open one of
                               its containers or its own criteria)
  minas/pequena, minas/mediana, minas/grande   chain of the mine entrances (mines.ADVANCEMENTS): enter one of each size
  costa/faro, costa/naufragio, costa/camarote  lighthouses and shipwrecks (coast.ADVANCEMENTS): enter a lighthouse, a
                               wrecked galleon and open the chest in its cabin
  unicas/cronista              (challenge) collect the sheets of the Chronicle of the Heralds (STORY of each module,
                               custom_data heraldia_historia; one inventory_changed criterion per sheet, all required)
  tesoro/fragmento, tesoro/cofre   treasure hunt (treasure.py): obtain a fragment and open the buried chest
Optional contract in each unicas/ module (see unicas/__init__.py): ADVANCEMENT = {"icono", "tesoro", "tesoro_objeto", "extra"}.
Rewards: experience only (Owner's decisions: nothing that breaks progression).
"""
from themes import FAMILIES, THEMES
from uniques._common.pieces import GUARDIAN_TAG
from uniques._common import chest_loot

NS = "heraldia"
BACKGROUND = "minecraft:gui/advancements/backgrounds/adventure"
ROOT_ICON, VILLAGES_ICON, UNIQUES_ICON = "minecraft:filled_map", "minecraft:bell", "minecraft:compass"
DEFAULT_ICON, GUARDIAN_ICON, TREASURE_ICON = "minecraft:filled_map", "minecraft:iron_sword", "minecraft:chest"
# Experience (moderate): a village is worth a simple vanilla advancement, challenges a big vanilla one.
XP = {"familia": 20, "aldeas": 250, "descubrir": 50, "guardian": 100, "tesoro": 50, "extra": 30, "unicas": 500,
      "trofeos": 500, "cronista": 500, "mediana": 10, "medianas": 150, "mediana_extra": 20}
MEDIUMS_ICON = "minecraft:oak_sign"
TROPHIES_ICON, CHRONICLE_ICON = "minecraft:armor_stand", "minecraft:written_book"
DEFAULT_TREASURE_TABLES = ("premium",)
TREASURE_MARK = "heraldia_tesoro"   # custom_data of the items in a fixed-content chest (tesoro_objeto)

# Common texts; %s is the name of the family, the structure or the guardian.
TEXTS = {
    "raiz": (("Heraldia", "Heraldia"),
             ("Entra en una aldea Heraldia, una estructura única, una mediana o una mina",
              "Enter a Heraldia village, a unique structure, a medium structure or a mine")),
    "familia": (("%s", "%s"), ("Entra en una aldea Heraldia de la familia %s", "Enter a Heraldia village of the %s family")),
    "aldeas": (("Trotamundos de Heraldia", "Heraldia Globetrotter"),
               ("Entra en una aldea de cada una de las 12 familias", "Enter a village of each of the 12 families")),
    "descubrir": (("%s", "%s"), ("Descubre la estructura única «%s»", "Discover the unique structure “%s”")),
    "guardian": (("%s", "%s"), ("Derrota al guardián de «%s»", "Defeat the guardian of “%s”")),
    "tesoro": (("Tesoro: %s", "Treasure: %s"), ("Abre la cámara del tesoro de «%s»", "Open the treasure chamber of “%s”")),
    "unicas": (("Cartógrafo de leyendas", "Cartographer of Legends"),
               ("Descubre todas las estructuras únicas", "Discover every unique structure")),
    "trofeos": (("Sala de trofeos", "Hall of Trophies"),
                ("Consigue el trofeo de cada guardián de las estructuras únicas",
                 "Collect the trophy of every unique structure's guardian")),
    "mediana": (("Al borde del camino", "By the Wayside"),
                ("Encuentra una estructura mediana: una torre de vigía, una posada, un campamento, una ermita...",
                 "Find a medium structure: a watchtower, an inn, a camp, a hermitage...")),
    "medianas": (("Caminante", "Wayfarer"),
                 ("Encuentra una estructura mediana de cada tipo", "Find a medium structure of every type")),
    "medianas_nether": (("Caminante del Nether", "Nether Wayfarer"),
                        ("Encuentra una estructura mediana del Nether de cada tipo",
                         "Find a Nether medium structure of every type")),
    "medianas_end": (("Caminante del vacío", "Void Wayfarer"),
                     ("Encuentra una estructura mediana del End de cada tipo",
                      "Find an End medium structure of every type")),
    "cronista": (("Cronista", "Chronicler"),
                 ("Reúne todos los pliegos de la Crónica de los Heraldos",
                  "Gather every leaf of the Chronicle of the Heralds")),
}


def key(path, part):
    return f"advancements.{NS}.{path.replace('/', '.')}.{part}"


def comp(k, fallback, *args):
    c = {"translate": k, "fallback": fallback}
    if args:
        c["with"] = list(args)
    return c


def name_key(sid):
    return f"{NS}.unicas.{sid}.nombre"


def unique_name(sid, mod):
    n = getattr(mod, "DISPLAY_NAME", None) or {}
    fallback = sid.replace("_", " ").capitalize()
    return n.get("es_es", fallback), n.get("en_us", n.get("es_es", fallback))


def location(structures):
    return {"trigger": "minecraft:location", "conditions": {"player": {
        "type": "minecraft:entity_properties", "entity": "this", "predicate": {"minecraft:location": {"structures": structures}}}}}


def advancement(parent, icon, title, desc, criteria, frame="task", xp=0, requirements=None, **display):
    """26.3 advancement; without `requirements` any one of the criteria is enough."""
    adv = {"criteria": criteria,
           "display": dict({"icon": {"id": icon}, "title": title, "description": desc, "frame": frame}, **display),
           "requirements": requirements or [sorted(criteria)]}
    if parent:
        adv["parent"] = f"{NS}:{parent}"
    if xp:
        adv["rewards"] = {"experience": xp}
    return adv


def guardians(reg, sid):
    """[(mob type, CustomName)] of the unique structure's guardians, without repeating a type (pack.tag_guardians tags them)."""
    found = {}
    for name, t in reg.templates.items():
        if name.startswith(f"unicas/{sid}/"):
            for *_, n in t.entities:
                if f"{GUARDIAN_TAG}.{sid}" in (n.get("Tags") or []):
                    found.setdefault(str(n["id"]), n.get("CustomName"))
    return sorted(found.items())


def build(reg, modules, mediums_mods=None, mines_mod=None, coast_mod=None):
    """{path: advancement} and texts {"es_es": {...}, "en_us": {...}} (keys with their own text; the %s in the title and
    the description are filled in with "with")."""
    advs, lang = {}, {"es_es": {}, "en_us": {}}

    def text(path, kind, *args):
        """Translatable (title, description) of an advancement using the common texts of TEXTS[kind]."""
        (tes, ten), (desc_es, desc_en) = TEXTS[kind]
        for part, es, en in (("title", tes, ten), ("description", desc_es, desc_en)):
            lang["es_es"][key(path, part)], lang["en_us"][key(path, part)] = es, en
        fb = lambda s: s % tuple(a.get("fallback", "") for a in args) if args else s
        return comp(key(path, "title"), fb(tes), *([args[0]] if "%s" in tes else [])), \
            comp(key(path, "description"), fb(desc_es), *([args[0]] if "%s" in desc_es else []))

    title, desc = text("raiz", "raiz")
    root = {"aldea": location(f"#{NS}:aldeas"), "unica": location(f"#{NS}:unicas")}
    if mediums_mods:
        root["mediana"] = location(f"#{NS}:medianas")
    if mines_mod:
        root["mina"] = location(f"#{NS}:minas")
    if coast_mod:
        root["costa"] = location(f"#{NS}:costa")
    advs["raiz"] = advancement(None, ROOT_ICON, title, desc, root, requirements=[sorted(root)], background=BACKGROUND,
                               announce_to_chat=False, show_toast=False)
    if mediums_mods:   # medium structures (medianas/): any one and one of each type
        title, desc = text("medianas/descubrir", "mediana")
        advs["medianas/descubrir"] = advancement("raiz", MEDIUMS_ICON, title, desc,
                                                 {"mediana": location(f"#{NS}:medianas")}, xp=XP["mediana"])
        import dimensions
        # Walker: one of each type in the overworld; the Nether and End ones have their own advancement (dimensions.py)
        for dim, path, kind, emblem in ((dimensions.MAIN, "medianas/todas", "medianas", MEDIUMS_ICON),
                                       (dimensions.NETHER, "medianas/nether", "medianas_nether", "minecraft:crimson_fungus"),
                                       (dimensions.END, "medianas/end", "medianas_end", "minecraft:end_rod")):
            crit = {mid: location(f"#{NS}:medianas/{mid}") for mid, mod in mediums_mods if dimensions.dimension_of(mod) == dim}
            if not crit:
                continue
            title, desc = text(path, kind)
            advs[path] = advancement("medianas/descubrir", emblem, title, desc, crit,
                                     requirements=[[mid] for mid in sorted(crit)], frame="goal", xp=XP["medianas"])
        for mid, mod in mediums_mods:      # advancements specific to each type (ADVANCEMENTS, optional; see medianas/__init__.py)
            for ex in getattr(mod, "ADVANCEMENTS", ()):
                path = f"medianas/{mid}/{ex['id']}"
                for part, field in (("title", "titulo"), ("description", "descripcion")):
                    lang["es_es"][key(path, part)], lang["en_us"][key(path, part)] = ex[field]
                crit = ex.get("criterios") or {ex["tabla"]: {"trigger": "minecraft:player_generates_container_loot",
                                                             "conditions": {"loot_tables": f"{NS}:medianas/{mid}/{ex['tabla']}"}}}
                advs[path] = advancement("medianas/descubrir", ex["icono"], comp(key(path, "title"), ex["titulo"][0]),
                                         comp(key(path, "description"), ex["descripcion"][0]), crit,
                                         xp=ex.get("xp", XP["mediana_extra"]), requirements=[sorted(crit)])
    if mines_mod:   # mine entrances: small -> medium -> large chain (enter one of each size)
        parent = "raiz"
        for size in mines_mod.SIZES:
            d, path = mines_mod.ADVANCEMENTS[size], f"minas/{size}"
            for part, field in (("title", "titulo"), ("description", "descripcion")):
                lang["es_es"][key(path, part)], lang["en_us"][key(path, part)] = d[field]
            advs[path] = advancement(parent, d["icono"], comp(key(path, "title"), d["titulo"][0]),
                                     comp(key(path, "description"), d["descripcion"][0]),
                                     {size: location(f"#{NS}:minas/{size}")}, frame="goal" if size == "grande" else "task",
                                     xp=mines_mod.XP[size])
            parent = path
    if coast_mod:   # lighthouses and shipwrecks: enter one of each type and open the galleon's cabin chest
        for lid, d in coast_mod.ADVANCEMENTS.items():
            path = f"costa/{lid}"
            for part, field in (("title", "titulo"), ("description", "descripcion")):
                lang["es_es"][key(path, part)], lang["en_us"][key(path, part)] = d[field]
            if "tabla" in d:
                crit = {d["tabla"]: {"trigger": "minecraft:player_generates_container_loot",
                                     "conditions": {"loot_tables": coast_mod.table_ident(d["tabla"])}}}
            else:
                crit = {d["criterio"][0]: location(d["criterio"][1])}
            parent = f"costa/{d['padre']}" if d.get("padre") else "raiz"
            advs[path] = advancement(parent, d["icono"], comp(key(path, "title"), d["titulo"][0]),
                                     comp(key(path, "description"), d["descripcion"][0]), crit, xp=coast_mod.XP[lid],
                                     requirements=[sorted(crit)])
    # villages by family
    for fam, d in FAMILIES.items():
        es, en = d["nombre"]
        lang["es_es"][f"{NS}.familia.{fam}"], lang["en_us"][f"{NS}.familia.{fam}"] = es, en
        title, desc = text(f"aldeas/{fam}", "familia", comp(f"{NS}.familia.{fam}", es))
        advs[f"aldeas/{fam}"] = advancement("raiz", d["icono"], title, desc, {fam: location(f"#{NS}:aldeas/{fam}")},
                                            xp=XP["familia"])
    title, desc = text("aldeas/todas", "aldeas")
    advs["aldeas/todas"] = advancement("raiz", VILLAGES_ICON, title, desc,
                                       {fam: location(f"#{NS}:aldeas/{fam}") for fam in FAMILIES},
                                       requirements=[[fam] for fam in FAMILIES], frame="challenge", xp=XP["aldeas"])
    # unique structures: everything comes from the registry, a new unique structure gets its advancements without touching this module
    for sid, mod in modules:
        es, en = unique_name(sid, mod)
        lang["es_es"][name_key(sid)], lang["en_us"][name_key(sid)] = es, en
        uname = comp(name_key(sid), es)
        adv_entry = getattr(mod, "ADVANCEMENT", None) or {}
        base = f"unicas/{sid}"
        title, desc = text(f"{base}/descubrir", "descubrir", uname)
        advs[f"{base}/descubrir"] = advancement("raiz", adv_entry.get("icono", DEFAULT_ICON), title, desc,
                                                {"descubrir": location(f"{NS}:{base}")}, xp=XP["descubrir"])
        gs = guardians(reg, sid)
        if gs:
            gname = gs[0][1] or uname
            gname = {k: v for k, v in gname.items() if k in ("translate", "fallback")}
            _, desc = text(f"{base}/guardian", "guardian", uname)
            crit = {mob.split(":")[-1]: {"trigger": "minecraft:player_killed_entity", "conditions": {"entity": {
                "type": "minecraft:entity_properties", "entity": "this",
                # entity_tags reads the Tags without serializing the mob (cheaper than nbt); the type is checked first
                "predicate": {"minecraft:entity_type": mob, "minecraft:entity_tags": {"all_of": [f"{GUARDIAN_TAG}.{sid}"]}}}}}
                for mob, _ in gs}
            advs[f"{base}/guardian"] = advancement(f"{base}/descubrir", GUARDIAN_ICON, gname, desc, crit,
                                                   frame="goal", xp=XP["guardian"], requirements=[sorted(crit)])
        loot = getattr(mod, "LOOT", {})
        tables = [t for t in adv_entry.get("tesoro", DEFAULT_TREASURE_TABLES) if t in loot]
        crit = {t: {"trigger": "minecraft:player_generates_container_loot",
                    "conditions": {"loot_tables": f"{NS}:{base}/{t}"}} for t in tables}
        if adv_entry.get("tesoro_objeto"):
            crit["objeto"] = {"trigger": "minecraft:inventory_changed", "conditions": {"items": [adv_entry["tesoro_objeto"]]}}
        if crit:
            title, desc = text(f"{base}/tesoro", "tesoro", uname)
            advs[f"{base}/tesoro"] = advancement(f"{base}/descubrir", TREASURE_ICON, title, desc, crit, frame="goal",
                                                 xp=XP["tesoro"], requirements=[sorted(crit)])
        for ex in adv_entry.get("extra", ()):
            path = f"{base}/{ex['id']}"
            for part, field in (("title", "titulo"), ("description", "descripcion")):
                lang["es_es"][key(path, part)], lang["en_us"][key(path, part)] = ex[field]
            advs[path] = advancement(f"{base}/{ex.get('padre', 'descubrir')}", ex["icono"],
                                     comp(key(path, "title"), ex["titulo"][0]), comp(key(path, "description"), ex["descripcion"][0]),
                                     ex["criterios"], frame=ex.get("marco", "task"), xp=ex.get("xp", XP["extra"]),
                                     requirements=ex.get("requisitos"))
    title, desc = text("unicas/todas", "unicas")
    advs["unicas/todas"] = advancement("raiz", UNIQUES_ICON, title, desc,
                                       {sid: location(f"{NS}:unicas/{sid}") for sid, _ in modules},
                                       requirements=[[sid] for sid, _ in modules], frame="challenge", xp=XP["unicas"])
    # trophies: one per unique structure (TROPHY is mandatory, pack.build_all checks it), all required
    crit = {sid: {"trigger": "minecraft:inventory_changed",
                  "conditions": {"items": [chest_loot.trophy_predicate(sid, mod.TROPHY)]}} for sid, mod in modules}
    title, desc = text("unicas/trofeos", "trofeos")
    advs["unicas/trofeos"] = advancement("raiz", TROPHIES_ICON, title, desc, crit,
                                         requirements=[[sid] for sid in sorted(crit)], frame="challenge", xp=XP["trofeos"])
    # chronicle: one sheet per unique structure (STORY is mandatory, pack.build_all checks it), all required
    crit = {sid: {"trigger": "minecraft:inventory_changed", "conditions": {"items": [chest_loot.story_predicate(sid)]}}
            for sid, mod in modules}
    title, desc = text("unicas/cronista", "cronista")
    advs["unicas/cronista"] = advancement("raiz", CHRONICLE_ICON, title, desc, crit,
                                          requirements=[[sid] for sid in sorted(crit)], frame="challenge", xp=XP["cronista"])
    import treasure   # treasure hunt (T40): tesoro/fragmento and tesoro/cofre (and their texts, treasure.lang_advancements)
    advs.update(treasure.advancements())
    for language, texts in treasure.lang_advancements().items():
        lang[language].update(texts)
    return advs, lang


def structure_tags(modules):
    """Structure tags used by the advancements: heraldia:aldeas/<familia> and heraldia:unicas (all of them)."""
    tags = {f"aldeas/{fam}": [f"{NS}:{th['id']}{suf}" for th in THEMES if th["family"] == fam for suf in ("", "_grande")]
            for fam in FAMILIES}
    tags["unicas"] = [f"{NS}:unicas/{sid}" for sid, _ in modules]
    return tags


def write(out, reg, modules, jdump):
    """Writes the advancements and their tags; returns the texts to add to the mod's languages."""
    for path, values in structure_tags(modules).items():
        jdump(out, f"data/{NS}/tags/worldgen/structure/{path}.json", {"values": values})
    import mediums, mines
    import shore as coast
    advs, lang = build(reg, modules, mediums.modules(), mines, coast)
    for path, adv in advs.items():
        jdump(out, f"data/{NS}/advancement/{path}.json", adv)
    return lang
